let deq (q : 'a queue) : 'a =
  begin match q.head with
  | None -> failwith "empty"
  | Some n ->
    q.head <- n.next;
    if n.next = None then q.tail <- None;
    n.v
  end

type counter = { inc : unit -> int }
let mk_counter () : counter =
  let c = ref 0 in
  { inc = fun () -> c := !c + 1; !c }

